import {campaignAudience,marketingMetrics} from './marketing.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export const campaignStatus=value=>({borrador:'Borrador',Borrador:'Borrador',procesada:'Procesada',procesada_con_errores:'Procesada con errores',processing:'En proceso',pending_provider:'Pendiente de proveedor',excluded:'Excluido',failed:'Error',fallido:'Error',partial_failure:'Con errores',accepted_by_provider:'Aceptado por proveedor',enviado_al_proveedor:'Aceptado por proveedor',delivered:'Entrega confirmada',nuevo:'Nuevo',recurrente:'Recurrente',consulta:'Sin compras',inactivo:'Inactivo',todos_consentidos:'Todos con consentimiento'}[value]||value||'—');
const frameDocument=html=>`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'"></head><body style="margin:0">${html}</body></html>`;
export function transportSettingsView(status={}){
 const requested=status.requestedSender||'maryrojascordova20@gmail.com';
 const requestedVerified=status.senderVerified===true&&status.senderEmail===requested;
 return `<section class="dm-admin-card" style="margin-top:1rem"><h2>Correo y remitente</h2><p>Remitente solicitado: <strong>${esc(requested)}</strong> · ${requestedVerified?'Verificado':'Sin verificar'}</p>${status.senderEmail&&status.senderEmail!==requested?`<p>Remitente configurado: ${esc(status.senderEmail)} · ${status.senderVerified?'Verificado':'Sin verificar'}</p>`:''}<p>Procesamiento de campañas: disponible.</p><p>Transporte externo: ${status.externalEnabled&&status.providerConfigured?'Disponible':'Pendiente de configuración'}.</p></section>`;
}
export function marketingStatsView(data){
 const stats=marketingMetrics(data);
 return `<div class="dm-admin-stats">${[['Perfiles',stats.profiles],['Compradores',stats.buyers],['Suscriptores activos',stats.subscribers],['Campañas',stats.campaigns],['Procesamientos',stats.processed],['Pendientes de proveedor',stats.pending],['Excluidos',stats.excluded],['Errores',stats.errors],['Aceptados por proveedor',stats.accepted],['Entregas confirmadas',stats.delivered]].map(([label,value])=>`<article class="dm-admin-stat"><span>${label}</span><strong>${value}</strong></article>`).join('')}</div>`;
}
export function customerRow(person){
 return `<tr><td>${esc(person.name)}</td><td>${esc(person.email)}</td><td>${esc(String(person.registeredAt||'').slice(0,10))}</td><td>${person.status==='activo'?'Activa':'Desactivada'}</td><td>${campaignStatus(person.segment)} · ${person.purchaseCount} compra(s)${person.inactive?'<br><small>Inactivo por antigüedad</small>':''}</td><td>${person.unsubscribed?'Baja de suscripción':person.consentAllowed?'Autorizado':'Sin autorización'}</td><td><details><summary>${(person.campaignHistory||[]).length} resultado(s)</summary>${(person.campaignHistory||[]).map(entry=>`<p>${esc(entry.campaignId)}<br>${esc(campaignStatus(entry.status))} · ${esc(entry.processedAt||entry.acceptedAt||'')}</p>`).join('')}</details></td><td><div class="dm-admin-actions"><button type="button" class="dm-admin-button" data-panel-action="edit-customer" data-id="${esc(person.id)}">Editar</button><button type="button" class="dm-admin-button danger" data-panel-action="delete-customer" data-id="${esc(person.id)}">Eliminar</button></div></td></tr>`;
}
export function customersView(people){
 return `<section class="dm-admin-card"><h2>Crear o editar cliente</h2><form id="panel-customer-form" class="dm-admin-form"><input type="hidden" name="id"><div class="dm-admin-field"><label for="customer-name">Nombre</label><input id="customer-name" class="dm-admin-input" name="name" required minlength="2" maxlength="120"></div><div class="dm-admin-field"><label for="customer-email">Correo electrónico</label><input id="customer-email" class="dm-admin-input" name="email" type="email" required maxlength="254"></div><div class="dm-admin-field"><label for="customer-date">Fecha de registro</label><input id="customer-date" class="dm-admin-input" name="registeredAt" type="date"></div><div class="dm-admin-field"><label for="customer-status">Estado de la ficha</label><select id="customer-status" class="dm-admin-select" name="status"><option value="activo">Activa</option><option value="inactivo">Desactivada</option></select></div><div class="dm-admin-field"><label for="consent-source">Fuente del consentimiento</label><input id="consent-source" class="dm-admin-input" name="consentSource" maxlength="200"></div><div class="dm-admin-field"><label for="consent-date">Fecha del consentimiento</label><input id="consent-date" class="dm-admin-input" name="consentDate" type="date"></div><label><input type="checkbox" name="marketingConsent"> Autoriza comunicaciones comerciales</label><label><input type="checkbox" name="unsubscribed"> Baja de suscripción</label><div class="dm-admin-field full"><small>Nuevo: una compra. Recurrente: dos o más. La inactividad se calcula desde la última compra.</small></div><div class="dm-admin-actions"><button class="dm-admin-button primary" type="submit">Guardar cliente</button><button class="dm-admin-button" type="button" data-panel-action="reset-customer">Limpiar</button></div></form><div id="panel-message" aria-live="polite"></div></section><section class="dm-admin-card" style="margin-top:1rem"><h2>Directorio de clientes</h2><div class="dm-admin-filters"><input class="dm-admin-input" type="search" data-customer-search aria-label="Buscar clientes" placeholder="Buscar nombre o correo"><select class="dm-admin-select" data-customer-status aria-label="Estado"><option value="">Todos los estados</option><option value="activo">Activa</option><option value="inactivo">Desactivada</option></select><select class="dm-admin-select" data-customer-segment aria-label="Segmento"><option value="">Todos los segmentos</option><option value="consulta">Sin compras</option><option value="nuevo">Nuevo</option><option value="recurrente">Recurrente</option><option value="inactivo">Inactivo por antigüedad</option></select><select class="dm-admin-select" data-customer-consent aria-label="Consentimiento"><option value="">Todo consentimiento</option><option value="yes">Autorizado</option><option value="no">Sin autorización</option><option value="unsubscribed">Baja de suscripción</option></select><button type="button" class="dm-admin-button" data-panel-action="export-customers">Exportar CSV</button></div><div class="dm-admin-table-wrap"><table class="dm-admin-table"><thead><tr><th>Nombre</th><th>Correo</th><th>Registro</th><th>Estado</th><th>Segmento</th><th>Consentimiento</th><th>Historial</th><th>Acciones</th></tr></thead><tbody id="panel-customer-rows">${people.map(customerRow).join('')||'<tr><td colspan="8">No hay clientes para estos filtros.</td></tr>'}</tbody></table></div></section>`;
}
export function audienceView(data,campaign){
 const people=campaignAudience(data,campaign);
 return `<p><strong>${people.filter(person=>person.eligible).length}</strong> elegibles · <strong>${people.filter(person=>!person.eligible&&!person.error).length}</strong> excluidos · <strong>${people.filter(person=>person.error).length}</strong> errores</p><details><summary>Ver destinatarios y exclusiones</summary>${people.map(person=>`<p>${esc(person.email)} · ${esc(person.reason||'Autorizado')}</p>`).join('')||'<p>No hay contactos registrados.</p>'}</details>`;
}
export function campaignsView(data){
 const campaigns=data.campaigns||[];
 const runs=(data.sendHistory||[]).filter(run=>run.type==='campaign');
 const preview=frameDocument('<div style="padding:24px;color:#493329;font:18px Georgia,serif">Dulce Momento</div>');
 return `${marketingStatsView(data)}<div class="dm-admin-grid"><section class="dm-admin-card"><h2>Crear o editar campaña</h2><form id="panel-campaign-form" class="dm-admin-form"><input type="hidden" name="id">${[['title','Nombre',120],['subject','Asunto',160]].map(([name,label,max])=>`<div class="dm-admin-field full"><label for="campaign-${name}">${label}</label><input id="campaign-${name}" class="dm-admin-input" name="${name}" required maxlength="${max}"></div>`).join('')}<div class="dm-admin-field full"><label for="campaign-body">Contenido HTML</label><textarea id="campaign-body" class="dm-admin-textarea" name="body" required maxlength="100000"></textarea></div><div class="dm-admin-field full"><label for="campaign-text">Texto alternativo</label><textarea id="campaign-text" class="dm-admin-textarea" name="text" required maxlength="100000"></textarea></div><div class="dm-admin-field full"><label for="campaign-segment">Destinatarios</label><select id="campaign-segment" class="dm-admin-select" name="segment">${['todos_consentidos','nuevo','recurrente','inactivo','consulta'].map(segment=>`<option value="${segment}">${campaignStatus(segment)}</option>`).join('')}</select></div><button class="dm-admin-button primary" type="submit">Guardar borrador</button><button class="dm-admin-button" type="button" data-panel-action="reset-campaign">Nueva campaña</button></form><div id="panel-message" aria-live="polite"></div><div id="panel-draft-audience">${audienceView(data,{segment:'todos_consentidos'})}</div><h3>Vista previa</h3><div class="dm-admin-actions"><iframe title="Vista previa escritorio" sandbox="" referrerpolicy="no-referrer" style="width:min(100%,560px);height:300px;border:1px solid var(--line);border-radius:12px" srcdoc="${esc(preview)}"></iframe><iframe title="Vista previa móvil" sandbox="" referrerpolicy="no-referrer" style="width:220px;height:300px;border:1px solid var(--line);border-radius:12px" srcdoc="${esc(preview)}"></iframe></div></section><section class="dm-admin-card"><h2>Campañas guardadas</h2><div class="dm-admin-list">${campaigns.map(campaign=>{const completed=['procesada','procesada_con_errores','processing','enviado_al_proveedor'].includes(campaign.status);return `<article class="dm-admin-list-item"><div><strong>${esc(campaign.name||campaign.title)}</strong><p>${esc(campaign.subject)}</p><span class="dm-admin-tag">${esc(campaignStatus(campaign.status))}</span><p>${campaignStatus(campaign.segment)}</p>${audienceView(data,campaign)}<div class="dm-admin-actions"><button type="button" class="dm-admin-button" data-panel-action="edit-campaign" data-id="${esc(campaign.id)}">${completed?'Ver contenido':'Editar / Vista previa'}</button><button type="button" class="dm-admin-button" data-panel-action="duplicate-campaign" data-id="${esc(campaign.id)}">Duplicar</button><button type="button" class="dm-admin-button primary" data-panel-action="send-campaign" data-id="${esc(campaign.id)}" ${completed?'disabled':''}>Procesar campaña</button><button type="button" class="dm-admin-button danger" data-panel-action="delete-campaign" data-id="${esc(campaign.id)}" ${campaign.sendHistory?.length?'disabled':''}>Eliminar</button></div></div></article>`;}).join('')||'<p>No hay campañas guardadas.</p>'}</div></section><section class="dm-admin-card full"><h2>Historial y resultados</h2>${runs.map(run=>`<details><summary>${esc(run.snapshot?.name||campaigns.find(campaign=>campaign.id===run.campaignId)?.name||run.campaignId)} · ${esc(campaignStatus(run.status))} · ${esc(run.finishedAt||run.startedAt)}</summary><p>Asunto: ${esc(run.snapshot?.subject||'—')}</p><p>${Number(run.recipientCount)||0} elegibles · ${Number(run.excludedCount)||0} excluidos</p><div class="dm-admin-table-wrap"><table class="dm-admin-table"><thead><tr><th>Correo</th><th>Resultado</th><th>Detalle</th></tr></thead><tbody>${(run.results||[]).map(result=>`<tr><td>${esc(result.email)}</td><td>${esc(campaignStatus(result.status))}</td><td>${esc(result.error||result.reason||'')}${result.providerId?` · ${esc(result.providerId)}`:''}</td></tr>`).join('')}</tbody></table></div><details><summary>Contenido registrado</summary><pre style="white-space:pre-wrap">${esc(run.snapshot?.text||'')}</pre></details></details>`).join('')||'<p class="dm-admin-muted">Aún no hay procesamientos registrados.</p>'}</section></div>`;
}
